insert into public.shops (id, slug, owner_id, name, tagline, category_slug, campus_slug, verified, badge, about, since, image_placeholder, image_alt, slug_changed, created_at, updated_at) values
  ('5dba9183-5707-5177-a224-0bfdee2a207e', 'hair-studio', null, 'Hair studio', 'Braids, cornrows and wash days on campus.', 'hair-beauty', 'midrand', true, 'trusted', E'I''ve been braiding since high school and started taking bookings on campus in my first year.\nBring a picture of the style you want, and I''ll tell you how long it takes and which hair to buy.', '2025-02', '/placeholders/seller/hair-studio.svg', 'The hair studio at work', false, '2025-02-01T08:00:00.000Z', '2025-02-01T08:00:00.000Z'),
  ('3056fc1d-7bdb-5270-a963-1088eea42953', 'maths-tutor', null, 'Maths tutor', 'Exam prep that sticks, one hour at a time.', 'tutoring', 'midrand', true, 'responsive', 'I''m a third-year student who tutors first-years in Statistics 1 and Maths 1. We work through past papers together until the method sticks.', '2025-08', '/placeholders/seller/maths-tutor.svg', 'The maths tutor at work', false, '2025-08-01T08:00:00.000Z', '2025-08-01T08:00:00.000Z'),
  ('2c7ce17d-8dbc-5263-acf5-fdaf18ae80a5', 'home-bakery', null, 'Home bakery', 'Cupcakes and cookie boxes for any occasion.', 'food', 'midrand', true, 'trusted', 'I bake at home in Midrand and bring orders to campus in the morning. Cupcakes, cookie boxes and birthday cakes, with a day''s notice.', '2025-04', '/placeholders/seller/home-bakery.svg', 'The home bakery at work', false, '2025-04-01T08:00:00.000Z', '2025-04-01T08:00:00.000Z'),
  ('ed1ff35e-1d34-5a65-ad68-6fc7cbfa3561', 'design-studio', null, 'Design studio', 'Logos and posters for student hustles.', 'services', 'midrand', true, 'responsive', 'I study graphic design and make logos, posters and social media posts for student hustles. You get two rounds of changes and the files in every size you need.', '2025-11', '/placeholders/seller/design-studio.svg', 'The design studio at work', false, '2025-11-01T08:00:00.000Z', '2025-11-01T08:00:00.000Z'),
  ('25c6a1dd-3585-555a-80c8-45533d91a060', 'thrift-rack', null, 'Thrift rack', 'Pre-loved jackets and denim, washed and pressed.', 'fashion-thrift', 'pretoria', true, 'new-seller', 'I hunt the thrift shops for good jackets and denim, then wash and press everything before it''s listed. New stock most weeks.', '2026-09', '/placeholders/seller/thrift-rack.svg', 'The thrift rack at work', false, '2026-09-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('2d2c8ef0-03a1-5959-80fc-a5cd43eba9bc', 'code-coach', null, 'Code coach', 'Python and Java help before your practicals.', 'tutoring', 'pretoria', true, 'trusted', 'I''m in my final year of IT and help first- and second-years with Python and Java. Bring your practical and we''ll debug it together, step by step.', '2025-03', '/placeholders/seller/code-coach.svg', 'The code coach at work', false, '2025-03-01T08:00:00.000Z', '2025-03-01T08:00:00.000Z'),
  ('69009c43-010a-52f8-a0fd-9c657a7128ab', 'phone-fix', null, 'Phone fix', 'Cracked screens and batteries, same day.', 'services', 'bedfordview', true, 'responsive', 'I replace cracked screens and tired batteries on most Samsung and iPhone models. Most repairs are done the same day.', '2025-06', '/placeholders/seller/phone-fix.svg', 'The phone fix at work', false, '2025-06-01T08:00:00.000Z', '2025-06-01T08:00:00.000Z'),
  ('7fb877f0-b83d-5f32-a949-3b780600a62b', 'nail-bar', null, 'Nail bar', 'Gel, acrylics and nail art between lectures.', 'hair-beauty', 'cape-town-tyger-valley', true, 'responsive', 'Gel, acrylics and nail art, done between lectures at Tyger Valley. Book a slot and send me a picture of what you''d like.', '2025-09', '/placeholders/seller/nail-bar.svg', 'The nail bar at work', false, '2025-09-01T08:00:00.000Z', '2025-09-01T08:00:00.000Z'),
  ('492f65d7-7747-5174-9cbd-92b4f93d06d0', 'study-notes', null, 'Study notes', 'Typed summaries for first-year modules.', 'textbooks-notes', 'online', true, 'responsive', 'I type up clear summaries for first-year modules and tutor spreadsheets over video. Everything comes as a PDF, so you can study anywhere.', '2025-05', '/placeholders/seller/study-notes.svg', 'The study notes at work', false, '2025-05-01T08:00:00.000Z', '2025-05-01T08:00:00.000Z'),
  ('208ffba5-aad7-5626-86a4-d42abd1b49fa', 'res-kitchen', null, 'Res kitchen', 'Home-cooked lunch boxes, ordered by 10am.', 'food', 'durban-umhlanga', false, 'trusted', 'Home-cooked lunch boxes for students in res. Order by 10am and collect at lunchtime; the menu changes every week.', '2025-07', '/placeholders/seller/res-kitchen.svg', 'The res kitchen at work', false, '2025-07-01T08:00:00.000Z', '2025-07-01T08:00:00.000Z'),
  ('d8a8d1e4-fcb1-5be7-958c-4feb9c3ad7f7', 'tech-corner', '11c18c13-a088-55c2-bacc-a95b612da2ea', 'Tech corner', 'Calculators, headsets and chargers, tested before you buy.', 'tech', 'midrand', false, 'responsive', E'I test every calculator, headset and charger before I list it, so you know it works.\nAsk me anything about a listing. I usually reply within the hour.', '2026-03', '/placeholders/seller/tech-corner.svg', 'The tech corner at work', false, '2026-03-01T08:00:00.000Z', '2026-03-01T08:00:00.000Z'),
  ('2aa61adf-934e-56b0-8717-75a6ee4c7e10', 'book-swap', null, 'Book swap', 'Last year''s textbooks and notes at half the price.', 'textbooks-notes', 'midrand', false, 'trusted', 'I sell last year''s textbooks and notes at about half the bookshop price. If a book has notes in the margins, the listing says so.', '2025-01', '/placeholders/seller/book-swap.svg', 'The book swap at work', false, '2025-01-01T08:00:00.000Z', '2025-01-01T08:00:00.000Z'),
  ('5a0141af-dd2b-5e1a-bb74-807110be875b', 'res-deals', null, 'Res deals', 'Fridges, lamps and curtains from students moving out.', 'res-living', 'midrand', false, 'trusted', 'When students move out of res, I find their fridges, lamps and curtains a new home. Everything is cleaned and checked before it''s listed.', '2025-10', '/placeholders/seller/res-deals.svg', 'The res deals at work', false, '2025-10-01T08:00:00.000Z', '2025-10-01T08:00:00.000Z'),
  ('e9b88645-62fb-50bc-b184-837620461dc2', 'closet-clear-out', null, 'Closet clear-out', 'Good clothes that need a new home.', 'fashion-thrift', 'midrand', false, 'new-seller', 'Clearing out clothes I don''t wear any more. Everything is washed, and I''m happy to swap.', '2026-09', '/placeholders/seller/closet-clear-out.svg', 'The closet clear-out at work', false, '2026-09-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('db482894-7e48-5212-b961-3e8eb6db2db0', 'ticket-desk', null, 'Ticket desk', 'Spare tickets for events around campus.', 'tickets-events', 'midrand', false, null, 'Spare tickets for events around Midrand, sold at what I paid. I''ll help you change the name on the booking.', '2026-07', '/placeholders/seller/ticket-desk.svg', 'The ticket desk at work', false, '2026-07-01T08:00:00.000Z', '2026-07-01T08:00:00.000Z'),
  ('ad3e14ca-c11b-5958-b0e4-fc6aad1318ee', 'res-essentials', null, 'Res essentials', 'Kettles, lamps and the bits every res room needs.', 'res-living', 'pretoria', false, 'responsive', 'Kettles, lamps and the small things every res room needs. I''m on campus most days, so collecting is easy.', '2026-02', '/placeholders/seller/res-essentials.svg', 'The res essentials at work', false, '2026-02-01T08:00:00.000Z', '2026-02-01T08:00:00.000Z'),
  ('a7d0f5df-be14-5551-940d-1abe6b4e06ce', 'lash-lounge', null, 'Lash lounge', 'Classic and volume lashes by appointment.', 'hair-beauty', 'pretoria', false, 'trusted', 'Classic and volume lash sets by appointment. I''m taking a short break, and bookings open again soon.', '2025-05', '/placeholders/seller/lash-lounge.svg', 'The lash lounge at work', false, '2025-05-01T08:00:00.000Z', '2025-05-01T08:00:00.000Z'),
  ('9efcaf4e-60af-5a9c-9299-2b8e4ff85857', 'stationery-stop', null, 'Stationery stop', 'Paper, pens and highlighters in bundles.', 'stationery', 'pretoria', false, null, 'Paper, pens and highlighters in bundles, for less than buying them one at a time. I restock before every exam season.', '2026-06', '/placeholders/seller/stationery-stop.svg', 'The stationery stop at work', false, '2026-06-01T08:00:00.000Z', '2026-06-01T08:00:00.000Z'),
  ('4bcf1678-a60c-5bca-9257-4bf4a5f4058f', 'bookshelf', null, 'Bookshelf', 'Textbooks from finished modules.', 'textbooks-notes', 'bedfordview', false, 'trusted', 'Textbooks from modules I''ve finished, kept in good condition. Ask if you need a book that isn''t listed yet.', '2025-03', '/placeholders/seller/bookshelf.svg', 'The bookshelf at work', false, '2025-03-01T08:00:00.000Z', '2025-03-01T08:00:00.000Z'),
  ('a3dc85a2-7c38-5eee-bf04-829838be60ad', 'moving-out-sale', null, 'Moving-out sale', 'Everything from a res room, priced to go.', 'res-living', 'bedfordview', false, null, 'I''m moving out of res at the end of the term, so everything has to go. Free things go to whoever collects first.', '2026-09', '/placeholders/seller/moving-out-sale.svg', 'The moving-out sale at work', false, '2026-09-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('7c636a2e-861d-5a4d-9574-69e11fef8371', 'kitchen-kit', null, 'Kitchen kit', 'Ovens, kettles and pots for cooking in res.', 'res-living', 'bloemfontein', false, 'trusted', 'Ovens, kettles and pots for cooking in res, tested and cleaned. I can hold an item for a day while you arrange to collect it.', '2025-08', '/placeholders/seller/kitchen-kit.svg', 'The kitchen kit at work', false, '2025-08-01T08:00:00.000Z', '2025-08-01T08:00:00.000Z'),
  ('4ed4c683-0a66-5599-8430-b4ee07a6c6b2', 'weekend-market', null, 'Weekend market', 'Bikes, cameras and things worth a second life.', 'res-living', 'cape-town-mowbray', false, 'new-seller', E'Bikes, cameras and other things worth a second life, found at weekend markets around Cape Town.\nI''m open to swaps.', '2026-08', '/placeholders/seller/weekend-market.svg', 'The weekend market at work', false, '2026-08-01T08:00:00.000Z', '2026-08-01T08:00:00.000Z'),
  ('f48d9dca-66e8-5a9f-9c4a-7524fde841d6', 'accounting-tutor', null, 'Accounting tutor', 'Accounting 2 and 3, explained until it clicks.', 'tutoring', 'durban-umhlanga', false, 'trusted', 'I tutor Accounting 2 and 3 and explain each step until it clicks. Two-hour sessions, with past-paper questions to take home.', '2025-02', '/placeholders/seller/accounting-tutor.svg', 'The accounting tutor at work', false, '2025-02-01T08:00:00.000Z', '2025-02-01T08:00:00.000Z'),
  ('10022286-e32b-5b03-b343-84c8ba2e9566', 'study-desk', null, 'Study desk', 'Calculators and stationery for exam season.', 'stationery', 'east-london', false, null, 'Calculators and stationery for exam season. Whatever I can''t sell, I give away.', '2026-05', '/placeholders/seller/study-desk.svg', 'The study desk at work', false, '2026-05-01T08:00:00.000Z', '2026-05-01T08:00:00.000Z'),
  ('12321893-2cf9-5148-b5cc-b05b59887ef5', 'room-refresh', null, 'Room refresh', 'Curtains, rugs and cushions for a brighter res room.', 'res-living', 'nelson-mandela-bay', false, 'new-seller', 'Curtains, rugs and cushions to make a res room feel like home. Most things are under R200.', '2026-09', '/placeholders/seller/room-refresh.svg', 'The room refresh at work', false, '2026-09-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('c3465c09-fd6d-50d0-8b45-2c602a4e2b08', 'sports-kit', null, 'Sports kit', 'Jerseys and gym gear, washed and ready.', 'fashion-thrift', 'potchefstroom', false, 'responsive', 'Jerseys and gym gear from teams and players who''ve moved on. Everything is washed and ready to wear.', '2025-12', '/placeholders/seller/sports-kit.svg', 'The sports kit at work', false, '2025-12-01T08:00:00.000Z', '2025-12-01T08:00:00.000Z'),
  ('dab3fe17-8718-5a58-83c3-dc988008951f', 'drawing-office', null, 'Drawing office', 'Drawing sets and scales for engineering students.', 'stationery', 'vanderbijlpark', false, 'trusted', 'Drawing sets, scales and templates for engineering students, from someone who''s finished with them. Every set is complete.', '2025-04', '/placeholders/seller/drawing-office.svg', 'The drawing office at work', false, '2025-04-01T08:00:00.000Z', '2025-04-01T08:00:00.000Z'),
  ('fb669131-e04c-5e05-b3f9-94904eb533a9', 'cv-clinic', null, 'CV clinic', 'CVs and LinkedIn profiles that get replies.', 'services', 'online', false, 'trusted', 'I rewrite CVs and LinkedIn profiles for students looking for internships and first jobs. We start with a short video call about the jobs you want.', '2025-06', '/placeholders/seller/cv-clinic.svg', 'The cv clinic at work', false, '2025-06-01T08:00:00.000Z', '2025-06-01T08:00:00.000Z'),
  ('88d53553-0f90-5ef2-9923-8f48ec74cbea', 'logo-lab', null, 'Logo lab', 'Logos for student brands, paid for or swapped.', 'services', 'online', false, null, 'Logos for student brands, paid for or swapped for something I need, like photos or a website. Tell me about your brand and I''ll send three ideas.', '2026-08', '/placeholders/seller/logo-lab.svg', 'The logo lab at work', false, '2026-08-01T08:00:00.000Z', '2026-08-01T08:00:00.000Z'),
  ('0b3cce5d-6fce-5eff-b390-b64f34a606dd', 'crochet-corner', '15eea3f4-7e8b-5176-ab1d-91a512bb16ae', 'Crochet corner', 'Beanies, bags and bucket hats, made by hand.', 'fashion-thrift', 'pretoria', false, 'new-seller', E'I crochet between lectures and sell what I make.\nTell me your colours and I''ll make you a beanie or a bag to order.', '2026-10', null, '', false, '2026-10-10T12:20:00.000Z', '2026-10-10T12:20:00.000Z');
