  ('fs-003', '5a0141af-dd2b-5e1a-bb74-807110be875b', 'available', 'item', 'Res curtains, two panels', 'res-living', 'good', 0, false, 'cash', null, 'Two curtain panels that fit a res window. Free if you collect this week.', 'pickup', 'b941bfe8-f74b-5c7a-aa51-f782133d8057', 'midrand', '2026-10-08T14:00:00Z', '2026-10-08T14:00:00Z', '2026-10-08T14:00:00Z', null, null),
  ('fs-004', '88d53553-0f90-5ef2-9923-8f48ec74cbea', 'available', 'service', 'Logo design for a photo shoot', 'services', null, null, false, 'swap', 'a photo shoot for my brand', 'I''ll design your logo if you''ll take photos for my brand.', 'online', null, 'online', '2026-10-08T12:00:00Z', '2026-10-08T12:00:00Z', '2026-10-08T12:00:00Z', null, null),
  ('fs-005', 'a3dc85a2-7c38-5eee-bf04-829838be60ad', 'available', 'item', 'Hangers, bag of 20', 'res-living', 'good', 0, false, 'cash', null, 'Twenty plastic hangers, free to whoever collects first.', 'pickup', '75fb177e-8a75-5e37-ab87-b587a190fcc3', 'bedfordview', '2026-10-08T10:00:00Z', '2026-10-08T10:00:00Z', '2026-10-08T10:00:00Z', null, null),
  ('fs-006', '4ed4c683-0a66-5599-8430-b4ee07a6c6b2', 'available', 'item', 'Calculator for a textbook', 'tech', 'good', null, false, 'swap', 'an Accounting 1 textbook', 'A scientific calculator I no longer need. I''m swapping it for a first-year textbook.', 'pickup', '2dcb9b5b-e5a7-5184-9a88-deca28f16fa3', 'cape-town-mowbray', '2026-10-08T08:00:00Z', '2026-10-08T08:00:00Z', '2026-10-08T08:00:00Z', null, null),
