insert into public.messages (id, conversation_id, side, body, swap_offer, sent_at, read_at) values
  ('8ed6dfb1-6e36-5427-83c6-b066c25702f8', '56ba4d68-2c29-50b8-8706-b78b96e1f1bc', 'buyer', 'Hi! Is the headset still available? I''d like to swap for it if you''re open to that.', 'A JBL Go 3 Bluetooth speaker, about a year old', '2026-10-13T08:12:00.000Z', '2026-10-13T09:01:00.000Z'),
  ('c4e50324-a42f-5c98-b50f-037178577d5e', '56ba4d68-2c29-50b8-8706-b78b96e1f1bc', 'seller', E'Hi Thandi, it is. Can I see the speaker first?\nI''m at the library entrance after 12:00 most days.', null, '2026-10-13T09:05:00.000Z', null),
  ('d2f69861-a223-5f28-8c2f-f9c67334934f', '1c2c009f-9fd9-5f7f-8045-3dcb610fa39d', 'buyer', 'Hi! Is the calculator still available? I need it for my stats test on Friday.', null, '2026-10-12T10:20:00.000Z', '2026-10-12T10:45:00.000Z'),
  ('b09653d3-dbbf-52a9-973d-5914acb3a9a1', '1c2c009f-9fd9-5f7f-8045-3dcb610fa39d', 'seller', 'Yes, it is. I can meet you at the library entrance at 13:00 tomorrow.', null, '2026-10-12T10:48:00.000Z', '2026-10-12T11:00:00.000Z'),
  ('12488ce1-1ab5-5882-8f9f-74c551edde0c', '1c2c009f-9fd9-5f7f-8045-3dcb610fa39d', 'buyer', 'Perfect, see you there.', null, '2026-10-12T16:30:00.000Z', '2026-10-12T17:10:00.000Z');
