insert into public.requests (id, asker_id, title, category_slug, campus_slug, details, budget_zar, swap_welcome, needed_by, status, created_at, updated_at, closed_at, seed_offers, hidden_at, hidden_reason) values
  ('r-001', null, 'Accounting 1 tutor this week', 'tutoring', 'midrand', E'I''m stuck on adjustments and the trial balance before Friday''s test. Looking for someone who passed Accounting 1 to work through two past papers with me.\nEvenings on campus suit me best.', 300, false, '2026-10-16', 'open', '2026-10-13T07:30:00Z', '2026-10-13T07:30:00Z', null, 2, null, null),
  ('r-002', null, 'Graphic calculator to borrow for exams', 'tech', 'pretoria', 'My calculator stopped working and exams start on the 26th. I''d like to borrow a graphic calculator for three weeks. I can pay R100, or swap my Statistics 1 notes.', 100, true, '2026-10-26', 'open', '2026-10-12T18:10:00Z', '2026-10-12T18:10:00Z', null, 1, null, null),
  ('r-003', null, 'Birthday cake for Friday', 'food', 'midrand', 'A chocolate cake for my roommate''s birthday on Friday, big enough for ten people. Writing on top would be a bonus. I can collect on campus at lunchtime.', 350, false, '2026-10-16', 'open', '2026-10-12T09:45:00Z', '2026-10-12T09:45:00Z', null, 3, null, null),
  ('r-004', null, 'Second-hand bar fridge', 'res-living', 'bedfordview', 'Looking for a small bar fridge for my res room, in working order. I can collect anywhere near campus if you can help me carry it.', 1200, false, null, 'open', '2026-10-11T15:20:00Z', '2026-10-11T15:20:00Z', null, 0, null, null),
  ('r-005', null, 'Someone to fix my laptop hinge', 'services', 'cape-town-mowbray', 'The left hinge on my laptop cracked and the screen wobbles. I''d like it fixed rather than replaced. Open to offers on price.', null, false, '2026-10-20', 'open', '2026-10-11T08:05:00Z', '2026-10-11T08:05:00Z', null, 1, null, null),
  ('r-006', null, 'Lift to campus on Monday mornings', 'services', 'pretoria', E'I live about ten minutes from campus and have an 8am class every Monday. I''ll put in R200 a month for petrol if you drive past.\nIt''s for the rest of the semester.', 200, false, null, 'open', '2026-10-10T22:40:00Z', '2026-10-10T22:40:00Z', null, 2, null, null),
  ('r-007', null, 'Business Law 2 notes', 'textbooks-notes', 'online', 'Looking for clear summary notes for Business Law 2, especially contracts. A PDF is fine. I can pay R150 or swap my Business Management 2 notes.', 150, true, '2026-10-30', 'open', '2026-10-10T06:15:00Z', '2026-10-10T06:15:00Z', null, 4, null, null),
  ('r-008', null, 'Formal dress for a faculty dinner', 'fashion-thrift', 'bloemfontein', 'I need a long formal dress, size 34, for a faculty dinner on the 24th. Happy to buy, borrow or swap one of mine.', 400, true, '2026-10-24', 'open', '2026-10-09T19:30:00Z', '2026-10-09T19:30:00Z', null, 1, null, null),
  ('r-009', null, 'Desk chair that doesn''t wobble', 'res-living', 'cape-town-tyger-valley', 'My res chair is falling apart. Looking for a sturdy desk chair, ideally one that adjusts. I can collect from campus or nearby.', 300, false, null, 'open', '2026-10-09T10:00:00Z', '2026-10-09T10:00:00Z', null, 0, null, null),
  ('r-010', null, 'Catering for a society braai', 'food', 'durban-umhlanga', 'Our society is having a braai for about 20 people on the 31st. We need someone to do the meat and two salads; we''ll bring the drinks.', 1500, false, '2026-10-31', 'open', '2026-10-08T16:25:00Z', '2026-10-08T16:25:00Z', null, 2, null, null),
  ('r-011', null, 'Drawing set for Engineering Graphics', 'stationery', 'east-london', 'I need a full drawing set: compass, set squares and a scale ruler. Second-hand is fine as long as nothing is missing.', 250, false, '2026-10-19', 'open', '2026-10-08T07:50:00Z', '2026-10-08T07:50:00Z', null, 1, null, null),
  ('r-012', null, 'Box braids before graduation', 'hair-beauty', 'nelson-mandela-bay', 'Looking for someone to do medium box braids, waist length, the week before graduation. I''ll buy the hair if you tell me how many packs.', 450, false, '2026-11-27', 'open', '2026-10-07T13:35:00Z', '2026-10-07T13:35:00Z', null, 3, null, null),
  ('r-013', null, 'Laptop charger, Lenovo 65W', 'tech', 'potchefstroom', 'My laptop charger stopped working. I need a 65W Lenovo charger with a USB-C plug. Make me an offer, or I can swap a pair of wired headphones.', null, true, null, 'open', '2026-10-06T18:00:00Z', '2026-10-06T18:00:00Z', null, 0, null, null),
  ('r-014', null, 'Python help for my first practical', 'tutoring', 'vanderbijlpark', 'My first Python practical is due on the 23rd and my loops keep breaking. Looking for an hour or two of help, online or on campus.', 200, false, '2026-10-23', 'open', '2026-10-06T09:20:00Z', '2026-10-06T09:20:00Z', null, 1, null, null),
  ('r-015', null, 'Kettle for res', 'res-living', 'midrand', 'Looking for a working kettle for my res room. Collecting on campus is easiest.', 150, false, null, 'closed', '2026-10-03T12:00:00Z', '2026-10-03T12:00:00Z', null, 5, null, null),
  ('r-016', null, 'Two tickets to the spring concert', 'tickets-events', 'pretoria', 'Looking for two tickets to the spring concert on the 10th, at or below what you paid.', 300, false, '2026-10-10', 'closed', '2026-09-29T08:30:00Z', '2026-09-29T08:30:00Z', null, 2, null, null);
insert into public.hub_posts (id, kind, title, summary, place, body, campus_slug, starts_at, capacity, going, image_src, image_alt, published, published_at, author_id, created_at, updated_at) values
  ('h-001', 'event', 'Pitch night', 'Five student businesses pitch to Hub mentors, and the room votes for a crowd favourite.', 'Online, with a watch party at every Hub', E'Five student businesses pitch to a panel of Incubation Hub mentors. Each team gets five minutes to pitch and three minutes for questions.\n\n## How the night runs\n1. Doors open at 17:30 at your campus''s Hub, or join online.\n2. Pitches start at 18:00.\n3. Everyone votes for a crowd favourite before the panel announces its pick.\n\nCome to cheer, to learn, or to see what it takes. **Want to pitch next time?** Start with [how to get the Verified badge](/hub/h-017), then talk to the Hub on your campus.', null, '2026-10-14T16:00:00Z', 80, 12, '/placeholders/hub/h-001.svg', '', true, '2026-09-30T08:00:00Z', null, '2026-09-30T08:00:00Z', '2026-09-30T08:00:00Z'),
  ('h-002', 'office-hours', 'Office hours: pricing your hustle', 'Bring your price list and a mentor will check it against your costs and what students pay.', 'The Hub, Block C', E'Not sure if you''re charging too much or too little? Bring your price list, or just your costs, and a mentor will work through it with you.\n\n## Bring\n- What it costs you to make or deliver one item or session\n- Your prices now, if you have them\n- Two or three listings like yours on Vossie\n\nSlots are 20 minutes. Read [how to price your first listing](/hub/h-013) before you come.', 'midrand', '2026-10-15T11:00:00Z', null, null, '/placeholders/hub/h-002.svg', '', true, '2026-10-01T08:00:00Z', 'bfad90c4-30ec-5ca2-bf9c-ec7af7909917', '2026-10-01T08:00:00Z', '2026-10-01T08:00:00Z'),
  ('h-003', 'event', 'Market day on the lawn', 'An evening market for student sellers on the library lawn: come to buy, or bring your stock and sell.', 'The lawn outside the library', E'Student sellers set up on the lawn outside the library for an evening market. Come and buy, or bring your own stock and sell.\n\n## For sellers\n- Stalls are free, and Verified sellers choose their spot first.\n- Bring a table if you can. The Hub has ten to lend.\n- Card machines work best on mobile data: the Wi-Fi on the lawn is patchy.\n\nRead [meeting a buyer safely on campus](/hub/h-015) for the basics on cash and handovers.', 'pretoria', '2026-10-20T16:00:00Z', 40, 23, '/placeholders/hub/h-003.svg', '', true, '2026-10-02T08:00:00Z', null, '2026-10-02T08:00:00Z', '2026-10-02T08:00:00Z'),
  ('h-004', 'office-hours', 'Photo day for your shop', 'Book 15 minutes in the studio room and leave with photos of your products or your work.', 'Studio room, Block A', E'A Hub mentor sets up a light box and a plain backdrop in the studio room. Book a slot, bring up to five items or examples of your work, and leave with photos you can use on Vossie.\n\n- Clean your items first: dust shows up on camera.\n- Selling a service? Bring something that shows your work, like a finished set of nails or a printed logo.\n\nCan''t make it? Try [five phone tricks for better photos](/hub/h-014).', 'bedfordview', '2026-10-22T11:00:00Z', null, null, '/placeholders/hub/h-004.svg', '', true, '2026-10-05T08:00:00Z', null, '2026-10-05T08:00:00Z', '2026-10-05T08:00:00Z'),
  ('h-005', 'event', 'Hub mixer', 'Meet other student sellers and the Hub''s mentors over snacks at your campus''s Hub.', 'The Hub on every campus', E'An evening to meet other student sellers, swap ideas and put faces to the mentors. Every campus''s Hub hosts its own, with snacks from student food sellers.\n\nNo pitch and no slides. Just bring yourself and, if you like, a few business cards.', null, '2026-10-28T16:00:00Z', 120, 45, '/placeholders/hub/h-005.svg', '', true, '2026-10-07T08:00:00Z', null, '2026-10-07T08:00:00Z', '2026-10-07T08:00:00Z'),
  ('h-006', 'event', 'Selling online: photos that sell', 'A one-hour online workshop on taking listing photos with nothing but your phone.', 'Online', E'A one-hour workshop on taking photos that make people stop scrolling. All you need is your phone.\n\n## What we''ll cover\n1. Light: where to stand, and why a window beats a flash.\n2. Background: plain, tidy and the same every time.\n3. The first photo: the one buyers see in the grid.\n\nThere''s time for questions at the end. Send in a photo you''re unsure about when you RSVP, and we may use it as an example.', null, '2026-11-05T16:00:00Z', 200, 64, '/placeholders/hub/h-006.svg', '', true, '2026-10-08T08:00:00Z', null, '2026-10-08T08:00:00Z', '2026-10-08T08:00:00Z'),
  ('h-007', 'office-hours', 'Office hours: your first listing', 'Sit with a mentor and put your first listing on Vossie, from the title to the photos.', 'The Hub, Block C', E'Never listed anything before? Bring your phone and the thing you want to sell, and a mentor will help you list it in one sitting.\n\nWe''ll go through the title, the price, the photos and how buyers will reach you. Read [writing a listing people trust](/hub/h-016) first if you have time.', 'midrand', '2026-11-19T11:00:00Z', null, null, '/placeholders/hub/h-007.svg', '', true, '2026-10-09T08:00:00Z', 'bfad90c4-30ec-5ca2-bf9c-ec7af7909917', '2026-10-09T08:00:00Z', '2026-10-09T08:00:00Z'),
  ('h-008', 'event', 'End-of-year market', 'The last market of the year, on every campus: clear out, stock up or find a gift.', 'By the student centre on every campus', E'The last market of the year, on every campus at once. Students clearing out res sell what they don''t want to carry home, and student businesses sell gifts and food.\n\n- Stalls are free for students.\n- Free items go on the giveaway table.\n- Anything left at the end can go in the Hub''s donation box.', null, '2026-12-03T16:00:00Z', 60, 18, '/placeholders/hub/h-008.svg', '', true, '2026-10-10T08:00:00Z', null, '2026-10-10T08:00:00Z', '2026-10-10T08:00:00Z'),
  ('h-009', 'event', 'Back-to-campus pop-up', 'A pop-up for the first week back: second-hand textbooks, res kit and student services in one place.', 'Student centre foyer', E'A pop-up for the first week back, in the student centre foyer. Second-hand textbooks, res kit and student services, all in one place.\n\nSelling? Stalls go to Verified sellers first, then everyone else. **Buying?** Bring your module list, so you know which editions you need.', 'pretoria', '2027-01-28T16:00:00Z', 50, 6, '/placeholders/hub/h-009.svg', '', true, '2026-10-11T08:00:00Z', null, '2026-10-11T08:00:00Z', '2026-10-11T08:00:00Z'),
  ('h-010', 'event', 'Pitch night', 'The first pitch night of 2027: five new student businesses, one panel and a crowd favourite.', 'Online, with a watch party at every Hub', E'The first pitch night of the year. Five new student businesses pitch to a panel of Incubation Hub mentors, and the room votes for a crowd favourite.\n\nApplications to pitch open in January. Start with [how to get the Verified badge](/hub/h-017).', null, '2027-02-11T16:00:00Z', 80, 3, '/placeholders/hub/h-010.svg', '', true, '2026-10-12T08:00:00Z', null, '2026-10-12T08:00:00Z', '2026-10-12T08:00:00Z'),
  ('h-011', 'event', 'Hub open day', 'An open day at every campus''s Hub: meet the mentors and see what the Hub can do for your business.', 'The Hub on every campus', E'Every campus''s Hub opened its doors for the evening. Students met the mentors, heard how Vossie works and booked their first office hours.\n\nMissed it? The Hub runs [office hours](/hub?type=office-hours) through the year.', null, '2026-09-16T16:00:00Z', 150, 96, '/placeholders/hub/h-011.svg', '', true, '2026-09-01T08:00:00Z', null, '2026-09-01T08:00:00Z', '2026-09-01T08:00:00Z'),
  ('h-012', 'office-hours', 'Office hours: registering your business', 'A mentor walks you through registering a small business, step by step.', 'The Hub, Block C', E'Thinking of registering your business? A mentor will walk you through the steps, what it costs and what to have ready.\n\n- Your ID and proof of address\n- A name for your business, and two back-ups\n- A rough idea of what you''ll sell', 'midrand', '2026-09-24T11:00:00Z', null, null, '/placeholders/hub/h-012.svg', '', true, '2026-09-10T08:00:00Z', 'bfad90c4-30ec-5ca2-bf9c-ec7af7909917', '2026-09-10T08:00:00Z', '2026-09-10T08:00:00Z'),
  ('h-013', 'tip', 'How to price your first listing', 'Start from what''s already listed, add up your costs, and leave room to say yes to a fair offer.', null, E'Pricing is the first thing buyers look at, and the easiest thing to get wrong. Start with what''s already out there, then check it against your own costs.\n\n## Start from what''s out there\n1. Search Vossie for the same thing, or [browse what''s already listed](/browse).\n2. Note the lowest and highest prices for the same condition.\n3. Price yours somewhere in between, and say why in the description.\n\n## Check your costs\nFor food, services and anything you make, add up what one item or session costs you: ingredients, data, transport and your time. If the market price doesn''t cover it, **don''t go lower**. Change what you offer instead.\n\n## Leave room for a fair offer\nStudents like to ask for a little off. If you''d take R250, a price of R270 lets you say yes. *Firm prices are fine too*, as long as the listing says so.', null, null, null, null, '/placeholders/hub/h-013.svg', '', true, '2026-10-12T07:00:00Z', null, '2026-10-12T07:00:00Z', '2026-10-12T07:00:00Z'),
  ('h-014', 'tip', 'Five phone tricks for better photos', 'Daylight, a plain background and a clean lens do more for a listing than any filter.', null, E'Buyers decide in a second, and they decide on the first photo. You don''t need a good camera, just these five habits.\n\n1. **Use daylight.** Stand near a window, and turn the flash off.\n2. **Clear the background.** A plain wall, a sheet or a desk with nothing else on it.\n3. **Wipe the lens.** Phones live in pockets, and a smudge makes everything look old.\n4. **Show the whole thing first,** then the details: labels, scratches, the size tag.\n5. **Shoot straight on.** Hold the phone at the same height as the item.\n\nWant help in person? Book a slot on [photo day for your shop](/hub/h-004).', null, null, null, null, '/placeholders/hub/h-014.svg', '', true, '2026-10-09T07:00:00Z', null, '2026-10-09T07:00:00Z', '2026-10-09T07:00:00Z'),
  ('h-015', 'tip', 'Meeting a buyer safely on campus', 'Meet in a busy place on campus, in daylight, and check the item before any money moves.', null, E'Most sales on Vossie end with a handover on campus. A few habits keep them easy and safe.\n\n## Before you meet\n- Agree on the price and the place in your messages, so there are no surprises.\n- Pick a busy spot on campus, like the library entrance, during the day.\n- Tell a friend where you''re going.\n\n## At the handover\n- Let the buyer check the item before they pay.\n- For cash, count it there and then. For a transfer, wait until it shows in your account.\n- If something feels wrong, walk away. There will be other buyers.\n\nRead Vossie''s [safety tips](/safety) for more.', null, null, null, null, '/placeholders/hub/h-015.svg', '', true, '2026-10-06T07:00:00Z', null, '2026-10-06T07:00:00Z', '2026-10-06T07:00:00Z'),
  ('h-016', 'tip', 'Writing a listing people trust', 'Say what it is, what condition it''s in and how the handover works, in plain words.', null, E'A clear listing gets fewer questions and sells sooner. Write it the way you''d describe the item to a friend.\n\n## The title\nSay what it is, then what makes it different: “Casio calculator, exam approved” beats “Calculator for sale”.\n\n## The description\n- What''s included, and what isn''t.\n- The condition, honestly, with any marks or faults.\n- Where and when you can hand it over.\n\n*Tip:* if a buyer asks the same question twice, add the answer to the listing. When you''re ready, [start selling](/sell).', null, null, null, null, '/placeholders/hub/h-016.svg', '', true, '2026-10-01T07:00:00Z', null, '2026-10-01T07:00:00Z', '2026-10-01T07:00:00Z'),
  ('h-017', 'tip', 'How to get the Verified badge', 'Verified means the Hub has met you and checked your business. Here''s how to apply.', null, E'The Verified badge tells buyers the Incubation Hub has met you and checked your business. It''s free, and it takes about a week.\n\n## How it works\n1. Sell on Vossie for at least a month.\n2. Book [office hours](/hub?type=office-hours) and tell the mentor you''d like to be verified.\n3. Bring your ID and examples of your work. The mentor checks them with you.\n4. Once you''re verified, the badge shows on your shop and your listings.\n\nThe Hub can take the badge away if a seller stops keeping their promises to buyers.', null, null, null, null, '/placeholders/hub/h-017.svg', '', true, '2026-09-25T07:00:00Z', null, '2026-09-25T07:00:00Z', '2026-09-25T07:00:00Z'),
  ('h-018', 'tip', 'From side hustle to small business', 'Three signs your hustle is ready to grow, and what to do about each one.', null, E'Plenty of student businesses start as a favour for a friend. Here are three signs yours is ready for more.\n\n## You''re turning people away\nIf you''re fully booked most weeks, it''s time to raise your prices or find someone to help.\n\n## People ask the same questions\nWrite the answers into your listings and your shop''s About, so you can spend the time on the work.\n\n## You''re not sure where the money goes\nKeep a simple record of what comes in and what goes out, every week. A mentor can show you how in [office hours](/hub?type=office-hours).', null, null, null, null, '/placeholders/hub/h-018.svg', '', true, '2026-09-18T07:00:00Z', null, '2026-09-18T07:00:00Z', '2026-09-18T07:00:00Z');
